export function getArtikel(slug: string) {
  return artikelen.find((a) => a.slug === slug);
}

export function relatedArtikelen(slugs: string[]) {
  return slugs
    .map((s) => artikelen.find((a) => a.slug === s))
    .filter((a): a is Artikel => Boolean(a));
}
